# 30.10 film a friend (HE): real stock + one Wan clip (the man filming at the water's edge, Z-Image seed 301030).
# Pexels 4782364 (Waikiki wide, surfers small) and 4782485 (same session, a ride) by Taryn Elliott, free licence; Mixkit 15845, 1069, 1220 free licence.
[ -f /s17/gen/fm_split.mp4 ] && exit 0
G=/s17/gen; mkdir -p $G /tmp/px
UA="Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/126.0 Safari/537.36"
for id in 4782364 4782485; do [ -s /tmp/px/p$id.mp4 ] || curl -sSfL -A "$UA" -m 300 -o /tmp/px/p$id.mp4 https://videos.pexels.com/video-files/$id/$id-uhd_2560_1440_30fps.mp4; done
for id in 15845; do [ -s /tmp/px/m$id.mp4 ] || for q in 1080 720; do curl -sSfL -A "$UA" -m 300 -o /tmp/px/m$id.mp4 https://assets.mixkit.co/videos/$id/$id-$q.mp4 && break; done; done
cut(){ src=$1; ss=$2; t=$3; c0=$4; c1=$5; n=$6; sp=${7:-1}
  ffmpeg -v error -y -ss $ss -t $(awk "BEGIN{print $t*$sp}") -i /tmp/px/$src.mp4 -vf "setpts=PTS/$sp,scale=-2:1920:flags=lanczos,crop=1080:1920:'max(0,min(iw-1080,($c0+($c1-$c0)*t/$t)*iw-540))':0,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/$n.mp4; }
cut p4782364 1.0 7.0 0.45 0.45 fm_hook
cut p4782485 0.0 5.0 0.76 0.70 fm_ride
cut m15845 0.0 9.8 0.56 0.56 fm_long 2
ffmpeg -v error -y -ss 0 -t 19.5 -i /tmp/px/m15845.mp4 -filter_complex "[0]setpts=PTS/2,split[a][b];[a]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,boxblur=30:2,eq=brightness=-0.12[bg];[b]scale=1080:-2:flags=lanczos[fg];[bg][fg]overlay=0:(H-h)/2,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_far.mp4
ffmpeg -v error -y -i out/ci/d30/gen/fm_board_raw.mp4 -vf "scale=-2:1920:flags=lanczos,crop=1080:1920,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_board.mp4
ffmpeg -v error -y -i out/ci/d30/gen/fm_film_raw.mp4 -vf "scale=-2:1920:flags=lanczos,crop=1080:1920,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_film.mp4
# hook: the same wave twice (Pexels 4782485): top = whole wide frame (surfer is a dot), bottom = tight crop on the surfer. Phone viewfinder clips: wide (1x) and zoom (3x) on black.
ffmpeg -v error -y -ss 0 -t 5.0 -i /tmp/px/p4782485.mp4 -filter_complex "[0]split[a][b];[a]crop=1633:1440:'max(0\,min(iw-1633\,if(lt(t\,1)\,1715+(1945-1715)*(t-0)/1\,if(lt(t\,2)\,1945+(1960-1945)*(t-1)/1\,if(lt(t\,3)\,1960+(1825-1960)*(t-2)/1\,if(lt(t\,4)\,1825+(1894-1825)*(t-3)/1\,if(lt(t\,5)\,1894+(2050-1894)*(t-4)/1\,2050)))))-816))':'max(0\,min(ih-1440\,if(lt(t\,1)\,820+(855-820)*(t-0)/1\,if(lt(t\,2)\,855+(850-855)*(t-1)/1\,if(lt(t\,3)\,850+(920-850)*(t-2)/1\,if(lt(t\,4)\,920+(1000-920)*(t-3)/1\,if(lt(t\,5)\,1000+(1010-1000)*(t-4)/1\,1010)))))-720))',scale=1080:952:flags=lanczos[t];[b]crop=600:529:'max(0\,min(iw-600\,if(lt(t\,1)\,1715+(1945-1715)*(t-0)/1\,if(lt(t\,2)\,1945+(1960-1945)*(t-1)/1\,if(lt(t\,3)\,1960+(1825-1960)*(t-2)/1\,if(lt(t\,4)\,1825+(1894-1825)*(t-3)/1\,if(lt(t\,5)\,1894+(2050-1894)*(t-4)/1\,2050)))))-300))':'max(0\,min(ih-529\,if(lt(t\,1)\,820+(855-820)*(t-0)/1\,if(lt(t\,2)\,855+(850-855)*(t-1)/1\,if(lt(t\,3)\,850+(920-850)*(t-2)/1\,if(lt(t\,4)\,920+(1000-920)*(t-3)/1\,if(lt(t\,5)\,1000+(1010-1000)*(t-4)/1\,1010)))))-264))',scale=1080:952:flags=lanczos[bb];color=c=0x2D242A:s=1080x16:r=30[d];[t][d][bb]vstack=3,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_split.mp4
ffmpeg -v error -y -ss 0 -t 5.0 -i /tmp/px/p4782485.mp4 -vf "scale=1080:608:flags=lanczos,pad=1080:1920:0:656:black,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_vf1.mp4
ffmpeg -v error -y -ss 0 -t 5.0 -i /tmp/px/p4782485.mp4 -vf "crop=1067:600:'max(0\,min(iw-1067\,if(lt(t\,1)\,1715+(1945-1715)*(t-0)/1\,if(lt(t\,2)\,1945+(1960-1945)*(t-1)/1\,if(lt(t\,3)\,1960+(1825-1960)*(t-2)/1\,if(lt(t\,4)\,1825+(1894-1825)*(t-3)/1\,if(lt(t\,5)\,1894+(2050-1894)*(t-4)/1\,2050)))))-533))':'max(0\,min(ih-600\,if(lt(t\,1)\,820+(855-820)*(t-0)/1\,if(lt(t\,2)\,855+(850-855)*(t-1)/1\,if(lt(t\,3)\,850+(920-850)*(t-2)/1\,if(lt(t\,4)\,920+(1000-920)*(t-3)/1\,if(lt(t\,5)\,1000+(1010-1000)*(t-4)/1\,1010)))))-300))',scale=1080:608:flags=lanczos,pad=1080:1920:0:656:black,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_vf3.mp4
ffmpeg -v error -y -i out/ci/d30/gen/fm_film2_raw.mp4 -vf "scale=-2:1920:flags=lanczos,crop=1080:1920,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_film2.mp4
curl -sSfL -A "$UA" -m 300 -o /tmp/px/k8155541.mp4 https://videos.pexels.com/video-files/8155541/8155541-uhd_2560_1440_25fps.mp4 && ffmpeg -v error -y -ss 8 -t 2 -i /tmp/px/k8155541.mp4 -vf "scale=-2:1920:flags=lanczos,crop=1080:1920:'0.52*iw-540':0,fps=25,format=yuv420p" -an -c:v libx264 -crf 15 $G/fm_paddle.mp4
ffmpeg -v error -y -ss 17.6 -t 4.0 -i app-screens/ScreenRecording_09-28-2026_15-24-29_1.mp4 -vf "crop=1080:1920:0:240,fps=25,format=yuv420p" -an -c:v libx264 -crf 14 $G/fm_replay.mp4
# app: upload flow, HE recording 28.09 (1_4): 12-17 s choose the video and "who is the surfer" (0-8 s has private photos: never)
ffmpeg -v error -y -ss 12.0 -t 5.0 -i app-screens/ScreenRecording_09-28-2026_10-56-35_1_4.mp4 -vf "crop=1080:1920:0:240,fps=25,format=yuv420p" -an -c:v libx264 -crf 14 $G/fm_app.mp4
mkdir -p out/ci/d30/review; for f in $G/fm_*.mp4; do n=$(basename $f .mp4); ffmpeg -v error -y -i $f -vf "fps=4,scale=180:-2,tile=16x1" -frames:v 1 out/ci/d30/review/cut_$n.jpg; done
ls -la $G/fm_*
